const body = $input.first().json.body || $input.first().json;

const toEmail = body.to_email;
const intent = body.intent;
const userId = body.user_id;
const orgId = body.organization_id;
const toName = body.to_name || '';
const context = body.context || '';
const replyToId = body.reply_to_id || null;

if (!toEmail || !intent) {
  throw new Error('Missing required fields: to_email and intent are required');
}

if (!userId || !orgId) {
  throw new Error('Missing required fields: user_id and organization_id are required');
}

return [{
  json: {
    to_email: toEmail,
    to_name: toName,
    intent: intent,
    context: context,
    user_id: userId,
    organization_id: orgId,
    reply_to_id: replyToId
  }
}];

