const claudeResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

let parsed = {
  subject: 'Email from your assistant',
  body_html: '<p>Email content could not be generated.</p>',
  body_text: 'Email content could not be generated.'
};

try {
  const text = claudeResponse.content[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Use defaults
}

return [{
  json: {
    ...inputData,
    subject: parsed.subject,
    body_html: parsed.body_html,
    body_text: parsed.body_text
  }
}];

